void dcl_delete(dchainList &h, datatype x)
{
    dchainList dcl = h;   
    //遍历双向链表，寻找第一个值为x的结点

    while(dcl != NULL)
    {
        if(dcl->data == x) break;
        dcl = dcl->next;
    }

    if(dcl == NULL) return;  
    //h中不存在值为x的结点

    dchainList pre = dcl->pre, nxt = dcl->next;
    //pre和nxt分别为被删除结点的直接前驱和直接后继

    if(pre != NULL)
        pre->next = nxt;
    //pre的后继改为nxt

    if(nxt != NULL)
        nxt->pre = pre;
    //nxt的前驱改为pre

    if(dcl == h)
        h = nxt;
    //如果删除的是第一个结点，则用其直接后继表示的双向链表

    delete dcl;dcl = NULL;
}

