//检查字符串中的括号('(',')','[',']')是否合法,合法,返回true;否则返回false
bool check_brackets( string str ){
    int i,sz=str.size();

    stack<char>stk;

    for(i=0; i<sz; i++){
        if(str[i]=='(' || str[i]=='[') stk.push(str[i]);          //左括号入栈
        else{
            if(str[i]!=')' && str[i]!=']') continue;              //跳过非括号字符
            if(stk.empty()) return false;                          //栈为空,不合法
            char ch=stk.top();                                    //获取栈顶元素
            if(str[i]==')' && ch!='(' || str[i]==']' && ch!='[')  //栈顶元素与当前括
                                                                  //号不匹配,不合法
                return false;
            stk.pop();                                            //出栈
        }
    }
    if(! stk.empty()) return false;                               //栈非空,不合法
    return true;
}

