//处理ops栈顶op的运算结果：从栈opers中取两个数据v1,v，计算v op v1的结果并返回
void cal(stack<double>&opers,stack<char>&ops){
    double v,v1,ret;
    v1=opers.top(),opers.pop();             //右操作数
    v=opers.top(),opers.pop();              //左操作数
    char op=ops.top();ops.pop();            //运算符
    switch(op){
        case '+':ret=v+v1;break;
        case '-':ret=v-v1;break;
        case '*':ret=v*v1;break;
        case '/':
            if(v1==0) exit(0);              //分母为0
            ret=v/v1;break;
    }
    opers.push(ret);                        //计算结果入栈
}

//算术表达式求值
double calculate(string exp){
    stack<double>opers;
    stack<char>ops;
    int i,sz=exp.size(),v;
    for(i=0;i<sz;i++){
        if(isdigit(exp[i])){                //exp[i]为数字，将其后连续数字组装为一个
                                            //整数
            v=exp[i]-'0';
            while(++i<sz&&isdigit(exp[i]))
                v=v*10+exp[i]-'0';
            opers.push(v);                  //将组装的整数入栈
            --i;
        }
        else if(exp[i]=='(') ops.push(exp[i]);//exp[i]为左括号，直接加入ops
        else if(exp[i]=='*'||exp[i]=='/'){  //exp[i]为乘号或除号，消除ops栈顶的'*'和'/'
            while(!ops.empty()&&(ops.top()=='*'||ops.top()=='/'))
                cal(opers,ops);
            ops.push(exp[i]);
        }
        else if(exp[i]=='+'||exp[i]=='-'||exp[i]==')'){//exp[i]为加号、减号或右括
                                                       //号，消除栈顶的'+'、'-'、'*'、'/'
            while(!ops.empty()&&ops.top()!='(')
                cal(opers,ops);
            if(exp[i]==')') ops.pop();
            else ops.push(exp[i]);
        }
    }
    while(!ops.empty())
        cal(opers,ops);
    return opers.top();
}

