typedef struct pNode{
    int coef;
    int exp;
    pNode * next;
    pNode():next(NULL){}
}*Poly;

Poly Add(Poly A,Poly B){
    Poly C=new pNode,r=C;
    Poly p=A->next,q=B->next;
    while(p!=NULL&&q!=NULL){
        Poly s=new pNode;
        if(p->exp>q->exp){
            s->coef=p->coef;
            s->exp=p->exp;
            p=p->next;
        }
        else if(p->exp<q->exp){
            s->coef=q->coef;
            s->exp=q->exp;
            q=q->next;
        }
        else{
            s->coef=p->coef+q->coef;
            s->exp=p->exp;
            p=p->next;
            q=q->next;
            if(s->coef==0){
            delete s;continue;
        }
        }
        r->next=s;r=s;
    }
    while(p!=NULL){
        r->next=new pNode;
        r=r->next;
        r->coef=p->coef;
        r->exp=p->exp;
        p=p->next;
    }
    while(q!=NULL){
        r->next=new pNode;
        r=r->next;
        r->coef=q->coef;
        r->exp=q->exp;
        q=q->next;
    }
    return C;
}
Poly Mul(Poly A,Poly B){
    Poly C=new pNode;
    Poly p=A->next;
    while(p!=NULL){
        Poly q=B->next;
        while(q!=NULL){
            int coef=p->coef*q->coef,exp=p->exp+q->exp;
            Poly r=C;
            while(r->next!=NULL&&r->next->exp>exp) r=r->next;
            if(r->next!=NULL&&r->next->exp==exp){
                r->next->coef+=coef;
                if(r->next->coef==0){
                    Poly s=r->next;
                    r->next=s->next;
                    delete s;
                }
            }
            else{
                Poly s=new pNode;
                s->coef=coef;s->exp=exp;
                s->next=r->next;r->next=s;
            }
            q=q->next;
        }
        p=p->next;
    }
    return C;
}

int swap(elementtype x,DList &h){
    if(h==NULL) return 0;
    DList p=h;
    while(p->next!=NULL && p->next->data!=x){
        p=p->next;
    }
    if(p->next==NULL) return 0;
    else{
        if(p==h) return 1;
        else{
            DList q = p->next;
            p->next = q->next;
            if(q->next!=NULL) q->next->pre=p;
            q->next = p;
            q->pre = p->pre;
            q->pre->next = q;
            p->pre=q;
            return 1;
        }
    }
}
