    cin>>n>>m;
    for(int i=0;i<n;i++)
        for(int j=0;j<m;j++)
            cin>>maze[i][j];
    vis[0][0]=true;
    int ret=0;
    dfs(0,0,ret);
    cout<<ret<<endl;
    return 0;
}

