//朴素模式匹配算法，判断主串s中是否包含模式串t
int bf(string s,string t){
    int i=0,j=0,k=0,sz_s=s.size(),sz_t=t.size();
    while(i<sz_s && j<sz_t){
        if(s[i]==t[j]){
            ++i,++j; //i,j同步后移
            if(j==sz_t) return k; //j到达模式串的最后一个字符的下一个位置，匹配成功
        }else
            ++k,i=k,j=0; //下一轮匹配主串从下一个字符开始，模式串从头开始
    }
    return -1; //匹配不成功
}

