 //删除2-3树t中键值为key的结点,rt为2-3树的根结点
void delete2_3(tree2_3 &rt,tree2_3 &t,int key){
    int i;
    if(t==NULL) return;

    for(i=0;i<t->num;i++){
        if(t->key[i]>key) break;
        else if(t->key[i]==key){
            //找到key的后继键值所在的叶结点
            if(t->child[0]!=NULL){
                tree2_3 tmp=t->child[i+1];

                while(tmp->child[0]!=NULL)
                    tmp=tmp->child[0];

                //用后继键值取代要删除的键值
                t->key[i]=tmp->key[0];

                //删除后继叶结点的第一个键值
                delete2_3_first(rt,tmp);
                return;
            }

            //t本身为叶结点
            if(i>0){
                //将待删除键值移到第一个位置
                for(int j=i;j>0;j--)
                    t->key[j]=t->key[j-1];
            }

            delete2_3_first(rt,t);
            return;
        }
    }

    //进入相应子树继续查找
    if(t->child[i]!=NULL)
        delete2_3(rt,t->child[i],key);
}

