void ini(int c) {
    int i;
    for (i = 0; i < c; i++)
        loser[i].idx = c, loser[i].run_idx = 0; //非叶结点

    for (i = c; i < 2 * c; i++)
        loser[i].idx = i - c; //叶结点

    for (i = 0; i < c; i++)
        leaf[i] = a[i];

    leaf[c] = -INF; //为了操作的一致性
}

//更新败者树的第cur个结点
void adjust(int cur) {
    int pa = cur >> 1;
    rss_node tmp = loser[cur];

    while (pa > 0) {
        if (loser[pa] < tmp)
            swap(loser[pa], tmp);
        pa >>= 1;
    }

    loser[0] = tmp;
}

//基于败者树的置换-选择排序，n为键值的总数，c为败者树叶结点的数量
void rss_sort(int n, int c) {
    int i, j, run_j = 0;
    ini(c);

    for (i = 2 * c - 1; i >= c; i--)
        adjust(i);

    i = c;

    while (1) {
        j = loser[0].idx;           //最小键值的下标
        run_j = loser[0].run_idx;   //一个顺串结束，考虑下一个顺串

        if (leaf[j] == INF)
            break;                 //所有键值都加入顺串，结束

        runs[run_j].push_back(leaf[j]); //将最小值加入当前顺串中

        /*
        if (runs[run_j].size() >= block_size) {
            //将结果存入磁盘
            runs[run_j].clear();
        }
        */

        int mi = leaf[j];
        rss_node tmp;
        tmp.idx = j;

        if (i >= n) {
            /* a中的键值处理完毕，从磁盘中加载其他未处理的键值，
               如果已全部加载，执行下面的操作 */
            leaf[j] = INF;       //如果键值全部加载进败者树，则添加一个INF
            tmp.run_idx = M + 1; //结点的顺串编号设置一个比所有顺串编号都大的值
        }
        else {
            leaf[j] = a[i++];    //更新叶结点的值
            tmp.run_idx = run_j;
        }

        if (leaf[j] < mi)
            tmp.run_idx++;      //新的键值<上一次所选取的键值，则属于下一个顺串

        loser[j + c] = tmp;      //更新叶结点
        adjust(j + c);          //更新败者树
    }
}

